/// Song credits, like Spotify's "View credits" and YouTube Music's "View
/// song credits": read from the notes YouTube writes for the music tracks
/// labels and distributors send it ("Provided to YouTube by …", the ℗
/// line, "Released on: …", then "Producer: …", "Composer, Lyricist: …").
library;

import 'package:youtube_explode_dart/youtube_explode_dart.dart';

/// What a track's auto-generated notes credit.
class SongCredits {
  const SongCredits({
    this.performers = const [],
    this.roles = const [],
    this.source,
    this.released,
    this.providedBy,
  });

  /// The artists on the "Title · Artist · Artist" line.
  final List<String> performers;

  /// Each role and who it credits, in the order the notes list them.
  final List<(String, List<String>)> roles;

  /// The ℗ line ("℗ 2011 Naïve"): the label, as Spotify's "Source".
  final String? source;

  /// The release date, as the notes write it ("2011-10-18").
  final String? released;

  /// Who sent the track to YouTube (the distributor).
  final String? providedBy;

  bool get isEmpty =>
      performers.isEmpty &&
      roles.isEmpty &&
      source == null &&
      released == null &&
      providedBy == null;
}

final _released = RegExp(r'^Released on: (.+)$');
final _role = RegExp(r'^([^:]{2,60}): (.+)$');

/// The credits in a track's [description] when YouTube wrote it for the
/// track; null for any other notes (a music video's own, say).
SongCredits? parseSongCredits(String description) {
  final lines = [
    for (final l in description.replaceAll('\r', '').split('\n'))
      l.trim().replaceAll(RegExp(r'\s+'), ' ')
  ];
  const provided = 'Provided to YouTube by ';
  const autoGenerated = 'Auto-generated by YouTube.';
  if (!lines.any((l) => l.startsWith(provided) || l == autoGenerated)) {
    return null;
  }
  String? providedBy, source, released;
  final performers = <String>[];
  final roles = <String, List<String>>{};
  // Roles come after the ℗ and release lines; before them, a colon is part
  // of a title ("Star Wars: …").
  var inRoles = false;
  for (final line in lines) {
    if (line.isEmpty || line == autoGenerated) continue;
    if (line.startsWith(provided)) {
      providedBy = line.substring(provided.length).trim();
      continue;
    }
    if (line.startsWith('℗') || line.startsWith('©')) {
      source ??= line;
      inRoles = true;
      continue;
    }
    if (_released.firstMatch(line) case final m?) {
      released = m.group(1)!.trim();
      inRoles = true;
      continue;
    }
    if (!inRoles) {
      if (performers.isEmpty && line.contains(' · ')) {
        performers.addAll(line
            .split(' · ')
            .skip(1)
            .map((a) => a.trim())
            .where((a) => a.isNotEmpty));
      }
      continue;
    }
    final m = _role.firstMatch(line);
    if (m == null || line.contains('://')) continue;
    final name = m.group(2)!.trim();
    for (final role in m.group(1)!.split(',')) {
      final r = role.trim();
      if (r.isEmpty) continue;
      final names = roles.putIfAbsent(r, () => []);
      if (!names.contains(name)) names.add(name);
    }
  }
  return SongCredits(
    performers: performers,
    roles: [for (final e in roles.entries) (e.key, e.value)],
    source: source,
    released: released,
    providedBy: providedBy,
  );
}

class SongCreditsService {
  SongCreditsService._();

  /// A video's notes (its description); tests put their own here.
  static Future<String> Function(String videoId) fetchDescription =
      _youtubeDescription;

  static final _memory = <String, SongCredits?>{};
  static final _inFlight = <String, Future<SongCredits?>>{};

  /// [videoId]'s credits; null when YouTube has none for it. Throws when
  /// they can't be fetched (offline), which isn't remembered.
  static Future<SongCredits?> load(String videoId) {
    if (_memory.containsKey(videoId)) return Future.value(_memory[videoId]);
    return _inFlight[videoId] ??= () async {
      try {
        final credits = parseSongCredits(await fetchDescription(videoId));
        if (_memory.length >= 200) _memory.clear();
        return _memory[videoId] = credits;
      } finally {
        _inFlight.remove(videoId);
      }
    }();
  }

  static Future<String> _youtubeDescription(String videoId) async {
    final yt = YoutubeExplode();
    try {
      return (await yt.videos.get(videoId)).description;
    } finally {
      yt.close();
    }
  }
}
